fn is_palindrome(text: Vec<char>) -> bool {
    // Requires that the input vector is not empty
    // Ensures that the return value is true if the input is a palindrome, false otherwise
    // The length of the input vector is invariant during the loop
    // The loop decreases the remaining iterations
    // The characters are compared in a case-insensitive manner

    let len = text.len();
    assert!(len >= 0); // Ensure the length is non-negative

    // Loop invariant: 0 <= i <= len / 2
    // At the start of the loop, we have 0 <= i < len / 2
    // We will check that the characters at positions i and len - 1 - i are equal (case insensitive)
    // The loop decreases the number of iterations left to check
    for i in 0..len / 2 {
        // Ensure that i is within bounds
        assert!(i < len / 2);
        assert!(len - 1 - i < len);

        let left_char = text[i];
        let right_char = text[len - 1 - i];

        // Check that the characters are equal in a case-insensitive manner
        if left_char.to_ascii_lowercase() != right_char.to_ascii_lowercase() {
            return false; // If any characters do not match, return false
        }
    }
    true // If all characters matched, return true
}